begin;
set local lock_timeout = '30s';

-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 9: CRM calendar and Google Calendar connection (docs/REDESIGN_PLAN.md phase 4, D-041). Additive only.
-- One calendar connection per staff user and provider; the OAuth refresh token lives in Supabase Vault (encrypted),
-- never in a readable column, never in the browser. Meetings belong to a CRM contact (and optionally an opportunity),
-- are idempotent by a client-generated key and record the real result of the external sync.

create table cw_prod.calendar_connections (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references cw_prod.profiles (id) on delete cascade,
  provider        text not null check (provider in ('GOOGLE')),
  account_email   text check (length(account_email) <= 254),
  calendar_id     text not null default 'primary' check (length(calendar_id) <= 200),
  scopes          text not null default '' check (length(scopes) <= 500),
  status          text not null default 'CONNECTED' check (status in ('CONNECTED', 'NEEDS_REAUTH', 'DISCONNECTED')),
  vault_secret_id uuid,                     -- Vault secret holding the refresh token (null once disconnected)
  connected_at    timestamptz not null default now(),
  last_checked_at timestamptz,
  last_error      text check (length(last_error) <= 300),
  unique (user_id, provider)
);

create table cw_prod.crm_events (
  id                uuid primary key default gen_random_uuid(),
  contact_id        uuid not null references cw_prod.crm_contacts (id) on delete cascade,
  opportunity_id    uuid references cw_prod.crm_opportunities (id) on delete set null,
  owner_id          uuid not null references cw_prod.profiles (id),
  title             text not null check (length(title) between 1 and 160),
  starts_at         timestamptz not null,
  ends_at           timestamptz not null,
  timezone          text not null default 'America/Sao_Paulo' check (timezone = 'America/Sao_Paulo'),
  location          text check (length(location) <= 300),
  description       text check (length(description) <= 2000),
  attendees         text[] not null default '{}' check (cardinality(attendees) <= 20),
  status            text not null default 'SCHEDULED' check (status in ('SCHEDULED', 'CANCELLED')),
  idempotency_key   uuid not null unique,     -- generated by the form: a repeated submit returns the same meeting
  sync_provider     text check (sync_provider in ('GOOGLE')),
  sync_status       text not null default 'LOCAL' check (sync_status in ('LOCAL', 'PENDING', 'SYNCED', 'FAILED')),
  external_event_id text check (length(external_event_id) <= 1024),
  sync_error        text check (length(sync_error) <= 300),
  synced_at         timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (ends_at > starts_at),
  check ((sync_status = 'LOCAL') = (sync_provider is null)),
  check (sync_status <> 'SYNCED' or external_event_id is not null)
);
create index on cw_prod.crm_events (contact_id, starts_at);
create index on cw_prod.crm_events (opportunity_id);
create index on cw_prod.crm_events (owner_id, starts_at);

alter table cw_prod.calendar_connections enable row level security, force row level security;
alter table cw_prod.crm_events           enable row level security, force row level security;
revoke all on cw_prod.calendar_connections, cw_prod.crm_events from public, anon, authenticated;

create trigger t_audit after insert or update or delete on cw_prod.crm_events for each row execute function cw_prod_private.audit_row();

-- Each staff member sees only their own connection; meetings follow the contact access rule (Gate 8).
create policy calendar_connections_read on cw_prod.calendar_connections for select to authenticated
  using (user_id = (select auth.uid()) and (select cw_prod_private.is_staff()));
create policy crm_events_read on cw_prod.crm_events for select to authenticated
  using ((select cw_prod_private.can_access_contact(contact_id)));
grant select (id, user_id, provider, account_email, calendar_id, scopes, status, connected_at, last_checked_at, last_error)
  on cw_prod.calendar_connections to authenticated;
grant select on cw_prod.crm_events to authenticated;
grant all on cw_prod.calendar_connections, cw_prod.crm_events to service_role;

-- ---------------------------------------------------------------- connection (called by the OAuth callback)
create function cw_prod.calendar_connection_save(p_provider text, p_email text, p_refresh_token text, p_scopes text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_conn cw_prod.calendar_connections; v_secret uuid;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  if p_provider <> 'GOOGLE' or coalesce(length(p_refresh_token), 0) < 10 then raise exception 'invalid connection' using errcode = '22023'; end if;
  select * into v_conn from cw_prod.calendar_connections where user_id = auth.uid() and provider = p_provider for update;
  if v_conn.vault_secret_id is not null then
    perform vault.update_secret(v_conn.vault_secret_id, p_refresh_token);
    v_secret := v_conn.vault_secret_id;
  else
    v_secret := vault.create_secret(p_refresh_token, 'cw_prod.calendar.' || p_provider || '.' || auth.uid()::text || '.' || gen_random_uuid()::text,
                                    'Campos Wealth calendar refresh token');
  end if;
  insert into cw_prod.calendar_connections (user_id, provider, account_email, scopes, status, vault_secret_id, connected_at, last_checked_at, last_error)
  values (auth.uid(), p_provider, nullif(lower(btrim(p_email)), ''), left(coalesce(p_scopes, ''), 500), 'CONNECTED', v_secret, now(), now(), null)
  on conflict (user_id, provider) do update
    set account_email = excluded.account_email, scopes = excluded.scopes, status = 'CONNECTED', vault_secret_id = v_secret,
        connected_at = now(), last_checked_at = now(), last_error = null
  returning id into v_conn.id;
  perform cw_prod_private.write_audit('PERMISSION_CHANGE', 'calendar_connections', v_conn.id::text, null, null,
    jsonb_build_object('provider', p_provider, 'status', 'CONNECTED'));
  return v_conn.id;
end $$;

-- Refresh token for the caller's own connection only (server-side use; never sent to the browser).
create function cw_prod.calendar_connection_token(p_provider text) returns text
language plpgsql stable security definer set search_path = '' as $$
declare v_secret uuid; v_token text;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  select vault_secret_id into v_secret from cw_prod.calendar_connections
   where user_id = auth.uid() and provider = p_provider and status = 'CONNECTED';
  if v_secret is null then return null; end if;
  select decrypted_secret into v_token from vault.decrypted_secrets where id = v_secret;
  return v_token;
end $$;

create function cw_prod.calendar_connection_mark(p_provider text, p_status text, p_error text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() or p_status not in ('CONNECTED', 'NEEDS_REAUTH') then perform cw_prod_private.deny(); end if;
  update cw_prod.calendar_connections set status = p_status, last_checked_at = now(), last_error = left(p_error, 300)
   where user_id = auth.uid() and provider = p_provider and status <> 'DISCONNECTED';
end $$;

-- Disconnect: the Vault secret is overwritten and unlinked (the server also revokes the token at Google).
create function cw_prod.calendar_disconnect(p_provider text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_conn cw_prod.calendar_connections;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  select * into v_conn from cw_prod.calendar_connections where user_id = auth.uid() and provider = p_provider for update;
  if not found then return; end if;
  if v_conn.vault_secret_id is not null then perform vault.update_secret(v_conn.vault_secret_id, 'revoked'); end if;
  update cw_prod.calendar_connections set status = 'DISCONNECTED', vault_secret_id = null, last_checked_at = now()
   where id = v_conn.id;
  perform cw_prod_private.write_audit('PERMISSION_CHANGE', 'calendar_connections', v_conn.id::text, null, null,
    jsonb_build_object('provider', p_provider, 'status', 'DISCONNECTED'));
end $$;

-- ---------------------------------------------------------------- meetings
-- Idempotent create: the same key returns the existing meeting (double submit, refresh, retry).
create function cw_prod.crm_event_create(p_key uuid, p_contact uuid, p_opportunity uuid, p_title text, p_starts timestamptz,
                                       p_ends timestamptz, p_location text, p_description text, p_attendees text[],
                                       p_sync_provider text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  perform cw_prod_private.require_contact(p_contact);
  select id into v_id from cw_prod.crm_events where idempotency_key = p_key;
  if found then
    if not exists (select 1 from cw_prod.crm_events where id = v_id and contact_id = p_contact) then perform cw_prod_private.deny(); end if;
    return v_id;
  end if;
  if p_opportunity is not null and not exists (select 1 from cw_prod.crm_opportunities where id = p_opportunity and contact_id = p_contact) then
    perform cw_prod_private.deny();
  end if;
  if exists (select 1 from unnest(coalesce(p_attendees, '{}')) a where a !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then
    raise exception 'invalid attendee' using errcode = '22023';
  end if;
  if p_sync_provider is not null and not exists (select 1 from cw_prod.calendar_connections
       where user_id = auth.uid() and provider = p_sync_provider and status = 'CONNECTED') then
    raise exception 'calendar not connected' using errcode = '22023';
  end if;
  insert into cw_prod.crm_events (contact_id, opportunity_id, owner_id, title, starts_at, ends_at, location, description, attendees,
                                idempotency_key, sync_provider, sync_status)
  values (p_contact, p_opportunity, auth.uid(), btrim(p_title), p_starts, p_ends, nullif(btrim(p_location), ''),
          nullif(btrim(p_description), ''), coalesce(p_attendees, '{}'), p_key, p_sync_provider,
          case when p_sync_provider is null then 'LOCAL' else 'PENDING' end)
  returning id into v_id;
  return v_id;
end $$;

-- Result of the external call, recorded only by the meeting owner. SYNCED requires the provider's event id.
create function cw_prod.crm_event_sync_result(p_id uuid, p_ok boolean, p_external_id text, p_error text) returns void
language plpgsql security definer set search_path = '' as $$
declare e cw_prod.crm_events;
begin
  select * into e from cw_prod.crm_events where id = p_id for update;
  if not found or e.owner_id is distinct from auth.uid() or e.sync_provider is null then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_contact(e.contact_id);
  if p_ok and nullif(btrim(p_external_id), '') is null then raise exception 'external id required' using errcode = '22023'; end if;
  update cw_prod.crm_events
     set sync_status = case when p_ok then 'SYNCED' else 'FAILED' end,
         external_event_id = case when p_ok then btrim(p_external_id) else external_event_id end,
         sync_error = case when p_ok then null else left(p_error, 300) end,
         synced_at = case when p_ok then now() else synced_at end, updated_at = now()
   where id = p_id;
end $$;

create function cw_prod.crm_event_cancel(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare e cw_prod.crm_events;
begin
  select * into e from cw_prod.crm_events where id = p_id for update;
  if not found then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_contact(e.contact_id);
  update cw_prod.crm_events set status = 'CANCELLED', updated_at = now() where id = p_id and status <> 'CANCELLED';
end $$;

revoke all on function
  cw_prod.calendar_connection_save(text, text, text, text), cw_prod.calendar_connection_token(text),
  cw_prod.calendar_connection_mark(text, text, text), cw_prod.calendar_disconnect(text),
  cw_prod.crm_event_create(uuid, uuid, uuid, text, timestamptz, timestamptz, text, text, text[], text),
  cw_prod.crm_event_sync_result(uuid, boolean, text, text), cw_prod.crm_event_cancel(uuid) from public, anon;
grant execute on function
  cw_prod.calendar_connection_save(text, text, text, text), cw_prod.calendar_connection_token(text),
  cw_prod.calendar_connection_mark(text, text, text), cw_prod.calendar_disconnect(text),
  cw_prod.crm_event_create(uuid, uuid, uuid, text, timestamptz, timestamptz, text, text, text[], text),
  cw_prod.crm_event_sync_result(uuid, boolean, text, text), cw_prod.crm_event_cancel(uuid) to authenticated;

commit;

select c.relname, c.relrowsecurity and c.relforcerowsecurity as rls_forcado from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cw_prod' and c.relname in ('calendar_connections','crm_events');
